def tutar(metin):
    """Türkçe biçimli tutarı sayıya çevirir: "1.234,56" -> 1234.56, "7.250" -> 7250.0, "7,5" -> 7.5."""
    metin = metin.strip()
    if "," in metin:
        tam, kurus = metin.split(",")
        tam = tam.replace(".", "")
        # virgülden sonrası 1 haneyse kesirli sayı (7,5 -> 7.5), değilse kuruş (89,90 -> 89.90)
        if len(kurus) == 1:
            return float(tam) + float(kurus) / 10
        return float(tam) + float(kurus) / 100
    if "." in metin:
        # Türkçe binlik ayraç: "7.250" -> 7250.0, "32.500" -> 32500.0
        return float(metin.replace(".", ""))
    return float(metin)

